## HTML Code

<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Aurevon</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    html, body { overflow-x: hidden; }

    body {
      background: #000;
      font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    }

    body.menu-open { overflow: hidden; }

    .font-instrument { font-family: "Instrument Serif", serif; }

    /* ——— Navbar ——— */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      z-index: 50;
      background: transparent;
      transition: background-color 500ms, backdrop-filter 500ms, -webkit-backdrop-filter 500ms;
    }

    .nav.scrolled {
      background: rgba(0, 0, 0, 0.8);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
    }

    .nav-inner {
      max-width: 1440px;
      margin: 0 auto;
      padding: 0 1.5rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 4rem;
    }

    .logo {
      color: #fff;
      font-size: 1.25rem;
      font-weight: 600;
      letter-spacing: -0.025em;
      text-decoration: none;
      z-index: 50;
      opacity: 0;
      transform: translateY(-1rem);
      transition: opacity 700ms cubic-bezier(0.16, 1, 0.3, 1), transform 700ms cubic-bezier(0.16, 1, 0.3, 1);
    }

    .nav-mounted .logo {
      opacity: 1;
      transform: translateY(0);
    }

    .nav-pill {
      display: none;
      align-items: center;
      gap: 0.5rem;
      padding: 0.5rem 1.25rem;
      border-radius: 9999px;
      border: 1px solid rgba(255, 255, 255, 0.2);
      background: transparent;
      color: rgba(255, 255, 255, 0.9);
      font-size: 0.875rem;
      font-family: inherit;
      cursor: pointer;
      opacity: 0;
      transform: translateY(-1rem);
      transition: opacity 700ms cubic-bezier(0.16, 1, 0.3, 1), transform 700ms cubic-bezier(0.16, 1, 0.3, 1), background-color 700ms cubic-bezier(0.16, 1, 0.3, 1);
    }

    .nav-mounted .nav-pill {
      opacity: 1;
      transform: translateY(0);
      transition-delay: 200ms, 200ms, 0ms;
    }

    .nav-pill:hover { background: rgba(255, 255, 255, 0.1); }

    .nav-flower {
      display: none;
      align-items: center;
      z-index: 50;
      opacity: 0;
      transform: translateY(-1rem);
      transition: opacity 700ms cubic-bezier(0.16, 1, 0.3, 1), transform 700ms cubic-bezier(0.16, 1, 0.3, 1);
    }

    .nav-mounted .nav-flower {
      opacity: 1;
      transform: translateY(0);
      transition-delay: 400ms;
    }

    .nav-flower svg {
      width: 1.75rem;
      height: 1.75rem;
      color: rgba(255, 255, 255, 0.9);
    }

    .hamburger {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 0.375rem;
      width: 2rem;
      height: 2rem;
      z-index: 50;
      position: relative;
      background: none;
      border: none;
      cursor: pointer;
      opacity: 0;
      transform: translateY(-1rem);
      transition: opacity 700ms cubic-bezier(0.16, 1, 0.3, 1), transform 700ms cubic-bezier(0.16, 1, 0.3, 1);
    }

    .nav-mounted .hamburger {
      opacity: 1;
      transform: translateY(0);
      transition-delay: 200ms;
    }

    .hamburger span {
      display: block;
      width: 1.5rem;
      height: 2px;
      background: #fff;
      transition: transform 500ms cubic-bezier(0.76, 0, 0.24, 1);
    }

    .hamburger.open span:first-child { transform: rotate(45deg) translateY(4px); }
    .hamburger.open span:last-child { transform: rotate(-45deg) translateY(-4px); }

    /* ——— Overlay ——— */
    .overlay {
      position: fixed;
      inset: 0;
      z-index: 40;
      background: #000;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      opacity: 0;
      visibility: hidden;
      transition: opacity 700ms cubic-bezier(0.76, 0, 0.24, 1), visibility 700ms cubic-bezier(0.76, 0, 0.24, 1);
    }

    .overlay.open {
      opacity: 1;
      visibility: visible;
    }

    .overlay-links {
