=== REDUCED MOTION ===
@media (prefers-reduced-motion: reduce) {
  .left-surface, .card-right .status-band, .status-band::before, .status-band::after
    { transition-duration: 1ms; }
  .live .dot, .status .dot, .orbit, .status-band::before { animation: none; }
